#!/usr/bin/env node
// gen-actor-columns.mjs — Constitution 1 §34 / §37: the table → actor-column map the Kysely actor-stamp plugin reads
// (packages/database/src/actor-columns.generated.ts), introspected from the REAL migrated schema (PGlite replay of
// apps/api/db/migrations, the same cached replay the pgtests use).
//
//   node apps/api/scripts/gen-actor-columns.mjs           write the generated file
//   node apps/api/scripts/gen-actor-columns.mjs --check   the gate (npm run check:actor-stamp): fail when
//     (a) the committed file differs from the schema (a migration added/removed an actor column without regenerating),
//     (b) a TENANT table (has tenant_id) that tracks updates (has updated_at) has no `updated_by` — unless it is
//         append-only (an update-refusing trigger), where nobody updates rows,
//     (c) a table with `deleted_at` has no `deleted_by` (Constitution 1 §55: a soft delete records who).
// Three older settings tables keep a TEXT updated_by their repositories write themselves (queue_assignment_settings,
// queue_assignment_rotation_state, voice_transcription_settings): it satisfies the gate; the plugin stamps uuid columns only.
// Flags per table: c = created_by uuid, u = updated_by uuid, d = deleted_by uuid, t = updated_at timestamp.
// An actor column that is a FOREIGN KEY is left out (the actor may be a staff user, a technician or a customer — a stamp
// must never make a write fail); a NOT NULL actor column is marked `!` (the plugin never writes NULL into it).
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { migratedPglite } from '../../../packages/testing/src/pgtest-schema.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const OUT = join(ROOT, 'packages', 'database', 'src', 'actor-columns.generated.ts');
const CHECK = process.argv.includes('--check');

const pg = await migratedPglite();
const q = async (s, p = []) => (await pg.query(s, p)).rows;
const cols = await q(`
  select c.table_name t, c.column_name col, c.udt_name udt, c.is_nullable = 'YES' nullable
    from information_schema.columns c join pg_tables pt on pt.schemaname = 'public' and pt.tablename = c.table_name
   where c.table_schema = 'public' and c.column_name in ('tenant_id','created_by','updated_by','deleted_by','updated_at','deleted_at')`);
const fkCols = new Set((await q(`
  select conrelid::regclass::text t, a.attname col from pg_constraint k
    join pg_attribute a on a.attrelid = k.conrelid and a.attnum = any(k.conkey)
   where k.contype = 'f' and a.attname in ('created_by','updated_by','deleted_by')`)).map((r) => `${r.t}.${r.col}`));
// Append-only: a BEFORE UPDATE trigger whose function refuses (raises) — audit_append_only, *_append_only, *_immutable…
const appendOnly = new Set((await q(`
  select distinct tg.tgrelid::regclass::text t from pg_trigger tg join pg_proc p on p.oid = tg.tgfoid
   where not tg.tgisinternal and (tg.tgtype & 16) <> 0 and p.prosrc ~* 'raise\\s+exception'
     and (p.proname ~* '(append_only|immutable|no_update|forbid|prevent)' or tg.tgname ~* '(append_only|immutable|no_update|forbid|prevent)')`)).map((r) => r.t));

const byTable = new Map();
for (const r of cols) {
  const e = byTable.get(r.t) ?? {}; e[r.col] = r; byTable.set(r.t, e);
}
const uuidActor = (e, t, col) => e[col] && e[col].udt === 'uuid' && !fkCols.has(`${t}.${col}`);
const lines = []; const problems = [];
for (const t of [...byTable.keys()].sort()) {
  const e = byTable.get(t);
  let flags = '';
  for (const [col, f] of [['created_by', 'c'], ['updated_by', 'u'], ['deleted_by', 'd']]) {
    if (uuidActor(e, t, col)) flags += f + (e[col].nullable ? '' : '!');
  }
  if (e.updated_at && /^timestamp/.test(e.updated_at.udt)) flags += 't';
  if (flags.replace('t', '')) lines.push(`  ${t}: '${flags}',`);
  else if (flags === 't' && e.tenant_id) lines.push(`  ${t}: '${flags}',`);
  if (e.tenant_id && e.updated_at && !e.updated_by && !appendOnly.has(t)) problems.push(`${t}: tenant table tracks updated_at but has no updated_by (add it in a migration, or make the table append-only)`);
  if (e.deleted_at && !e.deleted_by) problems.push(`${t}: has deleted_at but no deleted_by (Constitution 1 §55)`);
}

const body = `// GENERATED by apps/api/scripts/gen-actor-columns.mjs from the migrated schema — do not edit by hand.
// Regenerate after a migration that adds/removes created_by / updated_by / deleted_by / updated_at; the gate
// (npm run check:actor-stamp) fails when this file is stale. Flags: c = created_by uuid, u = updated_by uuid,
// d = deleted_by uuid ('!' = NOT NULL: never stamped with NULL), t = updated_at timestamp (bumped to now() on update).
// Tables listed only for 't' are tenant tables; platform tables with updated_at alone are not stamped.
export const ACTOR_COLUMNS: Readonly<Record<string, string>> = {
${lines.join('\n')}
};
`;

if (CHECK) {
  let current = '';
  try { current = readFileSync(OUT, 'utf8'); } catch { /* missing */ }
  if (current !== body) problems.unshift('packages/database/src/actor-columns.generated.ts is stale — run: node apps/api/scripts/gen-actor-columns.mjs');
  if (problems.length) { console.log(`check:actor-stamp FAILED (${problems.length})`); for (const p of problems.slice(0, 40)) console.log('  ' + p); process.exit(1); }
  console.log(`check:actor-stamp ok — ${lines.length} stamped tables; every tenant table with updated_at has updated_by (append-only exempt: ${appendOnly.size}); every deleted_at has deleted_by`);
  process.exit(0);
}
writeFileSync(OUT, body);
console.log(`wrote ${OUT} (${lines.length} tables)${problems.length ? `; ${problems.length} gate problem(s):\n  ` + problems.join('\n  ') : ''}`);
process.exit(0);
